/// Builds the AppsFlyer GCD (Get Conversion Data) rescue URL. Returns
/// `""` if the base is unavailable — callers treat that as "no rescue".
String pullGcdCallUrl(String appRef, String deviceId) {
  final String base = pullGcdBase();
  if (base.isEmpty) return '';
  return '$base$appRef?devkey=${pullAttrKey()}&device_id=$deviceId';
}
